idx = pd.date_range(pd.Timestamp('2009-12-01'), fit_end, freq='D')
samp = pd.read_csv('reference/feature_sample.csv', dtype={'line_id':str})
sc = pd.read_csv('reference/scores_reference.csv', dtype={'line_id':str})
sm = samp.merge(sc[['line_id','sku']], on='line_id')
tg = sm.groupby('sku')['f_sku_velocity'].first()

exact = {'84985a':1/470, '85035b':1/160, 'DCGSSBOY':6/130, 'DCGSSGIRL':20/130, '90187B':1/220}
def daily(sku):
    s = fit[fit['sku']==sku]
    d = s.groupby(s['placed_at'].dt.normalize())['units'].sum()
    return d.reindex(idx, fill_value=0.0)
# weekly ewm last/7, solve alpha per sku, see whether consistent
for adjust in [True, False]:
    for anchor in ['W','W-MON','W-TUE','W-WED']:
        alphas = {}
        ok = True
        for sku,t in exact.items():
            wk = daily(sku).resample(anchor).sum()
            def g(a): return wk.ewm(alpha=a, adjust=adjust).mean().iloc[-1]/7 - t
            try:
                # multiple roots possible; scan
                grid = np.linspace(1e-4, 0.999, 400)
                vals = [g(a) for a in grid]
                roots=[]
                for i in range(len(grid)-1):
                    if vals[i]*vals[i+1]<0:
                        roots.append(brentq(g, grid[i], grid[i+1]))
                alphas[sku]=roots
            except Exception as e:
                alphas[sku]=[]
        print(adjust, anchor, {k:[round(x,4) for x in v] for k,v in alphas.items()})
